INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('50d7d942-b640-401a-91e1-eb6acb5264cd', '71491f2d-8a2e-4689-be0c-b5becf82c45c', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'AI代码生成的灾难代价：人类审查失职的深度剖析与系统性反思_ai逻辑漏洞对话语-CSDN博客', 'other', '风险传导路径总结：AI 代码生成的固有缺陷通过三级传导形成系统风险——首先，概率预测机制导致逻辑正确性无法保证；其次，业务与架构理解不足使代码脱离实际需求；最终，质量退化与隐蔽错误降低系统鲁棒性，引发性能崩溃（如查询性能下降 60 倍）、数据错误（分布式交易不一致）、安全漏洞（权限越权）等灾难性后果。这一传导链条凸显：人类审查必须深度介入复杂逻辑设计，而非仅做语法层面的校验。', 0.8, 0.4, 4, NULL, 0.5);
