INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('9b8eec78-ab11-468d-a5bc-d16cfbbede8f', '71491f2d-8a2e-4689-be0c-b5becf82c45c', 'contradicting', 'https://www.freebuf.com/news/434891.html', '生成式AI面临的的主要安全风险以及解决策略 - FreeBuf网络安全行业门户', 'other', '第三方组件也可能因实施不当而产生风险。2023 年 3 月，ChatGPT 使用的 Redis 连接器库中存在一个漏洞，导致横向权限提升。不恰当的隔离机制导致用户能够查看其他用户会话的数据。 · 这一事件凸显了即插即用组件即使被广泛采用，如果不能安全集成，也会带来严重的安全隐患。 · 跟踪并审查依赖项：定期审核第三方软件包、库和插件。密切关注集成到模型训练或推理工作流程中的工具。被入侵的组件可能被用于窃取数据或篡改模型行为。', 0.5, 0.4, 4, NULL, 0.5);
