INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('02495685-50b4-40dd-970a-e1a7831a3549', 'd8261ea5-a545-42a7-ab35-98b3071cec18', 'supporting', 'https://blog.csdn.net/weixin_43172311/article/details/147104833', 'AI写代码的9大安全隐患_ai生成代码有何缺点-CSDN博客', 'other', '# AI生成的加密代码 def encrypt(data): # 这里发生了什么？AI自己也不知道 return magic_box(data) 当代码变成魔术表演，安全审计就成了观众席上的普通人。 · 就像自动驾驶时的低头玩手机，完全信任AI代码可能让你在漏洞出现时措手不及。', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('197a814b-3c10-4256-b6cf-e6f9673ef817', 'd8261ea5-a545-42a7-ab35-98b3071cec18', 'supporting', 'https://zhuanlan.zhihu.com/p/417418433', 'AI 生成的代码可信吗？编写的代码有 Bug 吗？ - 知乎', 'other', 'AI 生成错误代码的风险可能高得惊人。纽约大学的研究人员最近分析了 Copilot 生成的代码，发现对于某些安全性至关重要的任务，该代码<strong>大约有 40% 的时间包含安全漏洞</strong>。 · 参与分析的...', 0.9, 0.4, 4, NULL, 0.5);
