INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('f2fcfc85-4591-4efa-a176-2d96e3695f52', '6027e146-b706-42bc-b24f-9f2985b44a8a', 'supporting', 'https://blog.csdn.net/Deng945201314/article/details/149866176', 'AI生成代码的安全漏洞_斯坦福大学ai代码漏洞率-CSDN博客', 'other', '在软件开发效率提升300%的AI时代，代码生成工具正以惊人的速度渗透至金融、医疗、自动驾驶等关键领域。然而，斯坦福大学2022年对GitHub Copilot的89次实验揭示了一个残酷现实：<strong>近半数（45%）的AI生成代码存在安全缺陷</strong>，其中...', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('24ccc43f-83f0-4855-a934-147972b59567', '0b89a6ee-0b16-458a-9b79-507e06f42acd', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'AI代码生成的灾难代价：人类审查失职的深度剖析与系统性反思_ai逻辑漏洞对话语-CSDN博客', 'other', '人类对AI生成内容的过度信任正在形成系统性认知偏差。斯坦福大学2025年实验显示，79%的开发者会将AI生成的不安全代码误判为安全，这种&quot;验证错觉&quot;源于对AI输出的盲目信赖——开发者更关注代码&quot;能否运行&quot;而非&quot;是否安全&quot;，形成&quot;氛围编程&quot;（Vibe Coding）陷阱：完全依赖AI生成逻辑，不审核内部实现，仅通过表面功能测试便接受代码，最终积累大量&quot;信任债&quot;。 · AI生成效率的提升与审查资源的错配形成尖锐矛盾。Graphite报告指出，AI虽能加速代码生成（如每', 0.9, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('52f25fa8-3402-4cd1-a556-f4a2f51c2cfb', '0b89a6ee-0b16-458a-9b79-507e06f42acd', 'supporting', 'https://www.goupsec.com/news/19402.html', '三分之一的AI代码未经审核便进入生产环境 - GoUpSec', 'other', '软件开发目前面临的最大矛盾和威胁是：人类审核的速度已经跟不上AI生成代码的速度。 · 根据Cloudsmith最新发布的《2025工件管理报告》，AI代码生成工具已成为开发流程的重要参与者。在使用AI编程的开发者中，有42%表示...', 0.9, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('f7eb86a2-09fc-4a63-b15a-9a08da4118a4', '0b89a6ee-0b16-458a-9b79-507e06f42acd', 'contradicting', 'https://blog.csdn.net/2401_88760782/article/details/146288012', '二十五,如何审查AI生成的代码：5个必检查点_代码ai率检查-CSDN博客', 'other', '过度工程化的风险 看似精美的代码可能包含过度抽象或不必要的复杂性，导致维护困难。 · 复制已有代码的可能性 过于完美的代码可能是AI从训练数据中直接复制的，潜在带来许可证问题。 ... 一个金融科技公司使用AI生成了支付处理系统的代码。代码结构精美，使用了优雅的设计模式，看起来非常专业。然而，在生产环境中，他们发现代码过度抽象，难以调试和修改。最终，他们不得不重写大部分代码，采用更简单直接的方法。', 0.3, 0.4, 4, NULL, 0.5);
