INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('ba857b6a-1767-4ca5-bb2c-43412061e794', '25e86426-ec60-4dd3-a583-c0d9f766ec40', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'AI代码生成的灾难代价：人类审查失职的深度剖析与系统性反思_ai逻辑漏洞对话语-CSDN博客', 'other', '效率狂欢的悖论：AI代码生成工具在实现&quot;功能快速上线&quot;的同时，制造了更难偿还的技术债。GitClear对1.53亿行代码的分析显示，AI生成代码的&quot;搅动率&quot;（编写后两周内被修改的比例）是人工代码的2倍，且20%的依赖包为虚构不存在的库，直接导致苹果、微软等企业遭受供应链攻击。 · 狂欢背后的代价正以惊人速度显现。斯坦福大学2022年针对GitHub Copilot的实验揭示，45%的AI生成代码存在安全缺陷，其中Java语言漏洞率高达72%，跨站脚本（XSS）和日志注入漏洞占', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('9e515ed7-a7b0-40cb-b25a-4cac7d90a6c4', '25e86426-ec60-4dd3-a583-c0d9f766ec40', 'contradicting', 'https://hub.baai.ac.cn/view/22721', '斯坦福调研揭露AI写代码漏洞，共89次实验，出错率为40% - 智源社区', 'academic', '对于特定的问题，只有67%的受助组给出了正确答案，而79%的对照组给出了正确答案。结果表明，实验组「明显更有可能提供不安全的解决方案（p &lt; 0.05，使用 Welch 的不等方差 t 检验）」，并且也更有可能使用简单的密码，例如替换密码（p &lt; 0.01）， 并且不对最终返回值进行真实性检查。', 0.5, 0.95, 1, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('945e41c7-c26d-4ad7-9f9d-b22c39049dea', '25e86426-ec60-4dd3-a583-c0d9f766ec40', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151070223', 'AI辅助编程中的审查疏漏：灾难性后果深度解析_ai 大模型生成 代码 漏洞 带来的损失-CSDN博客', 'other', 'Sonar的《主流大语言模型编码人格报告》进一步量化了这些缺陷的严重性。该报告基于4442项Java任务的测试显示，AI生成的代码中，高达60%至70%的安全漏洞被评定为最高严重等级（BLOCKER），这意味着它们极有可能直接导致系统崩溃或数据泄露 。此外，高达90%的代码存在“代码异味”（Code Smells），即虽然不影响功能，但会降低代码可维护性和可读性的不良实践 。具体来看，路径遍历与注入漏洞（如SQL注入、XXE）占比最高，达到26%至34%，硬编码凭证（如A', 0.9, 0.4, 4, NULL, 0.5);
