INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('45e207bf-0ca2-441e-8a7e-d9d022e2b76d', '75a70e4d-739b-4c17-8986-eccf775de566', 'contradicting', 'https://www.secrss.com/articles/87726', 'AI Agent生态新威胁：Skills武器化与完整攻击链解析 - 安全内参 | 决策者的网络安全知识库', 'other', '但问题也源于此：Skills 多为第三方开发的代码，却拥有设备的实际系统访问权限，且不少 Skills 的安装步骤会引导用户执行 “终端粘贴命令”“下载运行二进制文件”“配置环境变量” 等操作。在黑客眼中，这层看似正常的操作指引，成了完美的社会工程攻击载体，让 Skills 生态既成为提升生产力的利器，也沦为恶意软件作者的温床。 · 为识别 OpenClaw Skills 的新型滥用模式，VirusTotal 在其Code Insight功能中新增了对 OpenClaw Skills 包（包括 ZIP 格式）的原生', 0.2, 0.4, 4, NULL, 0.5);
