INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('1cc4648e-dfd0-4ab4-9830-92655c08b235', '75a70e4d-739b-4c17-8986-eccf775de566', 'contradicting', 'https://www.80aj.com/2026/02/05/ai-agent-security-flaws/', 'AI Agent 的安全漏洞：90% 的开发者都忽略了', 'other', '去年一个 AI 客服 Agent 被黑客攻破，泄露了 5 万用户的个人信息。 问题不在模型，在开发者忽略了最基本的安全措施。 AI Agent 的安全问题比传统应用更复杂，因为它们有自主性。 漏洞一：权限过大 现状：大多数 Agent ...', 0.4, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('9555dd7d-75d7-4a23-8084-6b0f657c9db6', '75a70e4d-739b-4c17-8986-eccf775de566', 'supporting', 'https://developer.nvidia.com/blog/how-code-execution-drives-key-risks-in-agentic-ai-systems/', 'How Code Execution Drives Key Risks in Agentic AI Systems | NVIDIA Technical Blog', 'other', 'AI-driven applications are evolving from passive tools to agentic systems that generate code, make decisions, and take autonomous actions. This shift introduces a critical security challenge.', 0.7, 0.4, 4, NULL, 0.5);
