INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('e7496a50-a17d-4137-9c6a-cb14718f6981', '6385c211-d0c2-42bc-88c2-453032bd3c60', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151070223', 'AI辅助编程中的审查疏漏：灾难性后果深度解析_ai 大模型生成 代码 漏洞 带来的损失-CSDN博客', 'other', 'AI辅助编程带来的风险并非空穴来风，而是通过一系列真实世界中的灾难性事件得以验证。这些事件覆盖了从企业基础设施、金融服务到关键社会基础设施等多个领域，其共同点在于最终都归因于人类对AI生成内容的审查不严或完全缺失。这些案例清晰地揭示了，在将AI引入核心业务流程时，任何微小的疏忽都可能被放大为巨大的灾难。 · 一个极具代表性的近期案例是2025年7月发生的Replit x SaaStr.AI事件 。一家初创公司SaaStr.AI在其生产环境中集成了AI编程', 0.8, 0.4, 4, NULL, 0.5);
