INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('65bf01fa-cf72-4718-9a46-7453e04914aa', '4d90d7ef-e0c0-4bab-bf7c-c5f6ab4f7636', 'contradicting', 'https://www.secrss.com/articles/85850', '主流AI编程工具存在30多个漏洞，可导致数据被盗和远程命令执行 - 安全内参 | 决策者的网络安全知识库', 'other', '手动审查添加的源（例如通过URL），检查是否存在隐藏指令（HTML注释/CSS隐藏文本/不可见Unicode字符等）。 · 建议AI智能体和AI IDE开发者对LLM工具应用最小权限原则；最小化提示注入向量；强化系统提示；使用沙箱运行命令；进行针对路径遍历、信息泄露和命令注入的安全测试。', 0.5, 0.4, 4, NULL, 0.5);
