INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('0d6ab8ca-7273-4b87-820e-ca8079450272', '0c57d2a5-f37a-48ae-9d42-a0b64ce21a04', 'supporting', 'https://www.secrss.com/articles/80089', '三分之一的AI代码未经审核便进入生产环境 - 安全内参 | 决策者的网络安全知识库', 'other', '开发者对此并非毫无察觉：近八成（79.2%）开发者认为AI将加剧开源软件中的恶意软件威胁，其中30%更是认为风险将“显著上升”。仅有13%的开发者对AI在防御层面持乐观态度。 ... 在人工智能成为主力开发者的今天，代码审核机制却依然依赖人力。Cloudsmith报告披露，有三分之一的开发者并未对AI生成的代码进行部署前审核，这意味着大量未验证代码正被投入使用，对软件供应链构成巨大威胁。', 0.8, 0.4, 4, NULL, 0.5);
