INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('b0732306-5a35-4a53-8118-4a6a1e090087', 'e7dac692-01ec-473c-a507-00f5852e9ec8', 'supporting', 'https://blog.csdn.net/2301_76268839/article/details/144907950', 'AI创业公司的技术债务管理-CSDN博客', 'other', '在当今快速变化的商业环境中，AI创业公司面临着巨大的压力，需要快速开发和部署新的产品功能以满足市场需求。然而，这种快速发展往往会导致技术债务的积累，即由于快速开发而导致的代码质量下降、架构不合理、缺乏文档等问题。这些技术债务如果不及时偿还，会导致系统变得脆弱，维护成本增加，甚至影响产品的可用性和安全性。因此，AI创业公司需要建立有效的技术债务管理机制，以平衡快速发展和良好代码质量之间的关系。', 0.7, 0.4, 4, NULL, 0.5);
