INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('78cd5f96-0aaa-4b7d-9f67-5d95e951525c', 'c24aa47a-a6ba-48db-82e4-78a61a180a28', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'AI代码生成的灾难代价：人类审查失职的深度剖析与系统性反思_ai逻辑漏洞对话语-CSDN博客', 'other', 'AI生成效率的提升与审查资源的错配形成尖锐矛盾。Graphite报告指出，AI虽能加速代码生成（如每个开发者日均产出PR数量增加2.3倍），但人类审查能力并未同步提升，导致&quot;AI生成的更多PR&quot;反而降低了单位代码的审查深度。某电商平台使用AI生成200+页面组件时，安全团队仅能抽查5%的代码，直接导致支付接口存在越权漏洞，攻击者可通过修改请求参数获取他人订单信息。', 0.9, 0.4, 4, NULL, 0.5);
