INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('9c08be73-5c3e-4517-b282-0d1b7e92a9d9', 'f5ad9439-35f0-4add-85ac-370ae075d5c6', 'supporting', 'https://blog.csdn.net/Deng945201314/article/details/149866176', 'AI生成代码的安全漏洞_斯坦福大学ai代码漏洞率-CSDN博客', 'other', '在软件开发效率提升300%... Copilot的89次实验揭示了一个残酷现实：<strong>近半数（45%）的AI生成代码存在安全缺陷，其中Java语言漏洞率高达72%，远超Python（38%）和JavaScript（43%）。</strong>更令人震惊的是，跨站脚本（XSS）和日...', 0.7, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('724efb48-0dee-463a-93ef-d7b89e3676a1', 'f5ad9439-35f0-4add-85ac-370ae075d5c6', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151070223', 'AI辅助编程中的审查疏漏：灾难性后果深度解析_ai 大模型生成 代码 漏洞 带来的损失-CSDN博客', 'other', '根据Veracode发布《2025 Gen AI Code Security Report》，<strong>在对超过一百个大型AI模型的测试中，AI生成的代码在执行80项编程任务时，约有45%存在安全漏洞，其中大部分属于OWASP Top 10中最危险的漏洞类型</strong> 。这些漏洞主要集中在几个方面...', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('069fd5ea-d22d-42fa-9f45-59263157df6c', 'b324bfd7-3e2c-4323-97ce-10ada816c432', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'AI代码生成的灾难代价：人类审查失职的深度剖析与系统性反思_ai逻辑漏洞对话语-CSDN博客', 'other', '人类对AI生成内容的过度信任正在形成系统性认知偏差。斯坦福大学2025年实验显示，79%的开发者会将AI生成的不安全代码误判为安全，这种&quot;验证错觉&quot;源于对AI输出的盲目信赖——开发者更关注代码&quot;能否运行&quot;而非&quot;是否安全&quot;，形成&quot;氛围编程&quot;（Vibe Coding）陷阱：完全依赖AI生成逻辑，不审核内部实现，仅通过表面功能测试便接受代码，最终积累大量&quot;信任债&quot;。', 0.9, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('b2208f0d-5a42-45e6-b8c3-402a998ba5a9', 'f5ad9439-35f0-4add-85ac-370ae075d5c6', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'AI代码生成的灾难代价：人类审查失职的深度剖析与系统性反思_ai逻辑漏洞对话语-CSDN博客', 'other', 'AI生成效率的提升与审查资源的错配形成尖锐矛盾。Graphite报告指出，AI虽能加速代码生成（如每个开发者日均产出PR数量增加2.3倍），但人类审查能力并未同步提升，导致&quot;AI生成的更多PR&quot;反而降低了单位代码的审查深度。某电商平台使用AI生成200+页面组件时，安全团队仅能抽查5%的代码，直接导致支付接口存在越权漏洞，攻击者可通过修改请求参数获取他人订单信息。 · 审查者的专业能力已难以匹配AI代码的复杂性。开源社区统计显示，AI生成代码提交者自主排查错误的比例不足20%，而接收方审查者同样存在能力短板：某互联网公司架构师发现，应届生无法识别AI代码中嵌套循环导致的O(n²)复杂度隐患，这类性能缺陷在用户量突破百万级后引发系统雪崩。', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('533091d2-6633-42f9-af67-ae01726c5c0c', 'f5ad9439-35f0-4add-85ac-370ae075d5c6', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151070223', 'AI辅助编程中的审查疏漏：灾难性后果深度解析_ai 大模型生成 代码 漏洞 带来的损失-CSDN博客', 'other', 'AI辅助编程之所以能引发如此多的灾难性后果，其最深层的原因在于AI生成代码本身固有的、普遍存在的安全与质量缺陷。这些缺陷并非零星出现，而是呈现出系统性和规模化的特点，使得单纯依赖人工审查变得异常困难和不可靠。大量的研究和测试数据表明，AI在编码时几乎有一半的时间会选择一条不安全的路径，这为后续的风险埋下了伏笔 。 · 根据Veracode发布《2025 Gen AI Code Security Report》，在对超过一百个大型AI模型的测试中，AI生成的代码在执行80', 0.9, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('472e4294-a949-4f7f-a7cb-84fdce0c5554', '116a6e12-0b35-4ae0-b1d5-5cccff35c99f', 'supporting', 'https://blog.csdn.net/Deng945201314/article/details/149866176', 'AI生成代码的安全漏洞_斯坦福大学ai代码漏洞率-CSDN博客', 'other', '在软件开发效率提升300%... Copilot的89次实验揭示了一个残酷现实：<strong>近半数（45%）的AI生成代码存在安全缺陷，其中Java语言漏洞率高达72%，远超Python（38%）和JavaScript（43%）。</strong>更令人震惊的是，跨站脚本（XSS）和日...', 0.8, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('07d60c7c-d0c9-439a-8a99-63fe59ba9521', '116a6e12-0b35-4ae0-b1d5-5cccff35c99f', 'supporting', 'https://hub.baai.ac.cn/view/22721', '斯坦福调研揭露AI写代码漏洞，共89次实验，出错率为40% - 智源社区', 'academic', '斯坦福大学的学者们还引用了纽约大学的后续研究，然而因为它侧重于OpenAI的codex-davinci-002模型，而不是功能较弱的codex-cushman-001模型，两者都在 GitHub Copilot 中发挥作用，而GitHub Copilot本身是一个经过微调的后代GPT-3语言模型。 · 对于特定的问题，只有67%的受助组给出了正确答案，而79%的对照组给出了正确答案。结果表明，实验组「明显更有可能提供不安全的解决方案（p &lt; 0.05，使用 Welch 的不等方差 t 检验）」，并且也更有可能使用简单的密码，例如替换密码（p &lt; 0.01）， 并且不对最终返回值进行真实性检查。', 0.8, 0.95, 1, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('08b65293-f6d5-4c21-9ae3-1b84470fd3fc', '116a6e12-0b35-4ae0-b1d5-5cccff35c99f', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'AI代码生成的灾难代价：人类审查失职的深度剖析与系统性反思_ai逻辑漏洞对话语-CSDN博客', 'other', '狂欢背后的代价正以惊人速度显现。<strong>斯坦福大学2022年针对GitHub Copilot的实验揭示，45%的AI生成代码存在安全缺陷，其中Java语言漏洞率高达72%，跨站脚本（XSS）和日志注入漏洞占比超86%</strong>。这些隐蔽漏洞已转化为实际损失：英...', 0.9, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('b0b50304-ef19-4f6b-b6ca-cb5753c551f9', '116a6e12-0b35-4ae0-b1d5-5cccff35c99f', 'supporting', 'https://hub.baai.ac.cn/view/22721', '斯坦福调研揭露AI写代码漏洞，共89次实验，出错率为40% - 智源社区', 'academic', '斯坦福大学的学者们还引用了纽约大学的后续研究，然而因为它侧重于OpenAI的codex-davinci-002模型，而不是功能较弱的codex-cushman-001模型，两者都在 GitHub Copilot 中发挥作用，而GitHub Copilot本身是一个经过微调的后代GPT-3语言模型。 · 对于特定的问题，只有67%的受助组给出了正确答案，而79%的对照组给出了正确答案。结果表明，实验组「明显更有可能提供不安全的解决方案（p &lt; 0.05，使用 Welch 的不等方差 t 检验）」，并且也更有可能使用简单的密码，例如替换密码（p &lt; 0.01）， 并且不对最终返回值进行真实性检查。', 0.8, 0.95, 1, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('ff624f43-f049-4ef8-9309-f8ce0c052b01', '116a6e12-0b35-4ae0-b1d5-5cccff35c99f', 'supporting', 'https://blog.csdn.net/Deng945201314/article/details/149866176', 'AI生成代码的安全漏洞_斯坦福大学ai代码漏洞率-CSDN博客', 'other', 'AI生成的&quot;伪合理&quot;错误代码（幻觉代码）占比高达20%-40%，这类代码表面符合语法规范，实则存在逻辑暗礁。在某电商系统的支付模块开发中，AI生成的代码初看逻辑完整，但实测时频发金额计算错误——模型错误理解了&quot;满减优惠不可叠加&quot;的业务规则，虚构了不符合实际场景的处理逻辑。这种幻觉效应导致开发周期延长30%以上，更可能引发用户信任危机。 · AI代码助手在辅助编码时，若项目代码库存在安全漏洞，可能加剧风险扩散。斯坦福大学实验表明', 0.7, 0.4, 4, NULL, 0.5);
