INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('feee9d75-7531-4cd1-ae13-585b9739ec4d', 'e8a4da51-2b08-48e8-ad2e-45e139185f04', 'supporting', 'https://hub.baai.ac.cn/view/22721', '斯坦福调研揭露AI写代码漏洞，共89次实验，出错率为40% - 智源社区', 'academic', '斯坦福大学的学者们还引用了纽约大学的后续研究，然而因为它侧重于OpenAI的codex-davinci-002模型，而不是功能较弱的codex-cushman-001模型，两者都在 GitHub Copilot 中发挥作用，而GitHub Copilot本身是一个经过微调的后代GPT-3语言模型。 · 对于特定的问题，只有67%的受助组给出了正确答案，而79%的对照组给出了正确答案。结果表明，实验组「明显更有可能提供不安全的解决方案（p &lt; 0.05，使用 Welch 的不等方差 t 检验）」，并且也更有可能使用简单的密码，例如替换密码（p &lt; 0.01）， 并且不对最终返回值进行真实性检查。', 0.7, 0.95, 1, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('3f1a0adc-8a92-486d-a246-be968e830037', 'e8a4da51-2b08-48e8-ad2e-45e139185f04', 'supporting', 'https://blog.csdn.net/Jailman/article/details/151076846', 'AI代码生成的灾难代价：人类审查失职的深度剖析与系统性反思_ai逻辑漏洞对话语-CSDN博客', 'other', '在AI代码生成技术普及的背景下，人类审查机制的失效并非单一因素导致，而是心理认知偏差、流程设计缺陷与专业能力退化共同作用的系统性问题。本文构建&quot;心理—流程—能力&quot;三维分析框架，揭示AI时代人类审查责任的失守逻辑。 · 人类对AI生成内容的过度信任正在形成系统性认知偏差。斯坦福大学2025年实验显示，79%的开发者会将AI生成的不安全代码误判为安全，这种&quot;验证错觉&quot;源于对AI输出的盲目信赖——开发者更关注代码&quot;能否运行&quot;而非&quot;是否安全&quot;，形成&quot;氛围编程&quot;（Vibe Coding）陷阱：完全依赖AI生成逻辑，不审核内部实现，仅通过表面功能测试便接受代码，最终积累大量&quot;信任债&quot;。', 0.7, 0.4, 4, NULL, 0.5);
INSERT INTO evidence (id, edge_id, evidence_type, source_url, source_title, source_type, snippet, relevance_score, credibility_score, source_tier, published_date, freshness_score) VALUES ('9924033f-9b69-46b4-b74f-322e9408bd0c', 'e8a4da51-2b08-48e8-ad2e-45e139185f04', 'supporting', 'https://blog.csdn.net/Deng945201314/article/details/149866176', 'AI生成代码的安全漏洞_斯坦福大学ai代码漏洞率-CSDN博客', 'other', '在软件开发效率提升300%的AI时代，代码生成工具正以惊人的速度渗透至金融、医疗、自动驾驶等关键领域。然而，斯坦福大学2022年对GitHub Copilot的89次实验揭示了一个残酷现实：近半数（45%）的AI生成代码存在安全缺陷，其中Java语言漏洞率高达72%，远超Python（38%）和JavaScript（43%）。更令人震惊的是，跨站脚本（XSS）和日志注入漏洞占比超86%，这些高危漏洞源于AI模型对训练数据中不安全模式的无意识复制，暴露出当前AI代码生成技术的深层缺陷。', 0.8, 0.4, 4, NULL, 0.5);
